import {initialState,categories,groups,emojiChoices,ingredient} from './seed.js';
import {uid,clone,norm,round,fmt,quantity,ingredientKey,allocate,availability,remainingState,finishCooking,undoCooking,finishProduction,undoProduction,generateMenu,validateBackup,migrateState,units,meals,allowedMeals,newEntry,defaultModes,safeVideoUrl} from './core.js';
import {openStorage,saveStorage,readStorage} from './storage.js';
import {icons} from './icons.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.book}"/></svg>`;
const attrs=(action,id='')=>`data-action="${action}" data-id="${esc(id)}"`;
const button=(label,action,id='',cls='button')=>`<button type="button" class="${cls}" ${attrs(action,id)}${action==='quiz'?' aria-label="Подобрать меню"':action==='new-recipe'?' aria-label="Новый рецепт"':''}>${label}</button>`;
const iconButton=(label,action,id,type)=>`<button type="button" class="icon-button" ${attrs(action,id)} aria-label="${esc(label)}" title="${esc(label)}">${icon(type)}</button>`;
const options=(values,selected)=>values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const categoryClass=c=>({'Супы':'soup','Второе':'main-dish','Десерты':'dessert','Завтраки':'breakfast','Салаты':'salad'}[c]||'');
const foodIcon=r=>r.photo?`<img class="food-photo" src="${esc(r.photo)}" alt="">`:`<span class="food-icon ${categoryClass(r.category)}" aria-hidden="true">${esc(r.emoji||'🍽️')}</span>`;
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
let state,storageError='',saveQueue=Promise.resolve(),toastTimer,returnFocus,hasPrevious=false;
let view={page:location.hash.slice(1)||'recipes',search:'',category:'',freezerOnly:false,usesPrep:false,canFreeze:false,showEmpty:false,stockSearch:'',quiz:{},addMeal:null};
let recipeDraft,draftPhoto='',prepDraft,stockDraft;
const modal=$('#modal');
const recipe=id=>state.recipes.find(r=>r.id===id);
const prep=id=>state.prepTypes.find(p=>p.id===id);
const mealTitle=id=>meals.find(([m])=>m===id)?.[1]||id;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function commit(change,checkpoint=false){
 const task=saveQueue.then(async()=>{const next=typeof change==='function'?change(clone(state)):change;validateBackup(next);try{await saveStorage(next,checkpoint?state:undefined);if(checkpoint)hasPrevious=true;state=next;storageError='';render();return true;}catch(e){storageError='Не удалось сохранить. Скачай копию в «Моих данных» и проверь свободное место.';render();toast(storageError);return false;}});
 saveQueue=task.catch(()=>{});return task;
}
const mutate=fn=>commit(s=>{fn(s);return s;});
function go(page){view.page=page;if(location.hash==='#'+page)render();else location.hash=page;}
function showModal(title,body){returnFocus=document.activeElement;modal.innerHTML=`<header class="modal-head"><h2>${esc(title)}</h2>${iconButton('Закрыть','close','','close')}</header><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){modal.close();returnFocus?.isConnected&&returnFocus.focus();}
function dialogError(message){let el=$('.form-error',modal);if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');$('.modal-body',modal).append(el);}el.textContent=message;el.scrollIntoView({block:'nearest'});}
function ask(title,text,action,label='Подтвердить'){showModal(title,`<p>${esc(text)}</p><div class="modal-actions">${button('Отмена','close')}<button class="button primary" id="confirm-action">${esc(label)}</button></div>`);$('#confirm-action').onclick=async e=>{e.currentTarget.disabled=true;try{if(await action()!==false)closeModal();}catch(err){dialogError(err.message);e.currentTarget.disabled=false;}};}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function heading(title,actions=''){return `<header class="page-heading"><h1>${title}</h1><div class="actions">${actions}</div></header>`;}
function empty(text,action=''){return `<div class="empty"><p>${text}</p>${action}</div>`;}
function render(){
 if(!state)return;const focus=document.activeElement,focusId=focus?.id;let selection;try{selection=[focus.selectionStart,focus.selectionEnd];}catch{}
 const page=['recipes','menu','shopping','freezer','data'].includes(view.page)?view.page:'recipes';
 const counts={recipes:state.recipes.length,menu:state.menu.length,shopping:allocate(state).shopping.filter(i=>{const f=shoppingFlag(i);return !f.home&&!f.bought;}).length,freezer:state.stock.filter(s=>s.amount>0).length};
 $('#app').innerHTML=`${storageError?`<div class="storage-error" role="alert">${esc(storageError)}</div>`:''}<aside class="sidebar"><a class="brand" href="#recipes"><img src="./icon.svg" alt=""><span>На неделю</span></a><nav aria-label="Главная навигация">${[['recipes','book','Рецепты'],['menu','menu','Меню'],['shopping','bag','Покупки'],['freezer','snow','Морозилка']].map(([id,i,title])=>`<a href="#${id}" class="nav-link ${id===page?'active':''}" ${id===page?'aria-current="page"':''}><span class="nav-icon">${icon(i)}<span class="nav-count">${counts[id]}</span></span><span>${title}</span></a>`).join('')}</nav><div class="side-bottom">${button(`${icon('settings')}Мои данные`,'data','','nav-settings')}</div></aside><main class="main"><div class="topbar"><a class="mobile-brand" href="#recipes"><img src="./icon.svg" alt="">На неделю</a><span class="top-caption">Рецепты · меню · запасы</span><div class="actions">${iconButton('Мои данные и резервная копия','data','','settings')}${button(`${icon('plus')}<span>Новый рецепт</span>`,'new-recipe','','button primary')}</div></div>${({recipes:renderRecipes,menu:renderMenu,shopping:renderShopping,freezer:renderFreezer,data:renderData}[page])()}</main>`;
 if(focusId){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(selection?.[0]!=null)try{el.setSelectionRange(...selection);}catch{}}}
}
function renderRecipes(){
 const free=remainingState(state);const list=state.recipes.filter(r=>(!view.category||r.category===view.category)&&(!view.search||norm(r.title+' '+r.ingredients.map(i=>i.name).join(' ')).includes(norm(view.search)))&&(!view.freezerOnly||availability(free,r).has)&&(!view.usesPrep||r.preparations.length>0)&&(!view.canFreeze||!!r.freezePrepId));
 return `${heading('Рецепты',view.addMeal?`<span class="badge">Добавление: ${mealTitle(view.addMeal)}</span>${button('Готово','end-adding')}`:'')}<div class="toolbar"><label class="search">${icon('search')}<input id="recipe-search" type="search" aria-label="Найти рецепт или продукт" placeholder="Рецепт или продукт" value="${esc(view.search)}"></label>${button(`${icon('spark')}<span>Подобрать меню</span>`,'quiz')}</div><div class="chips">${['',...categories].map(c=>`<button class="chip ${view.category===c?'active':''}" data-action="category" data-value="${esc(c)}" aria-pressed="${view.category===c}">${esc(c||'Все')}</button>`).join('')}</div><div class="filters"><label class="check"><input type="checkbox" id="freezer-filter" ${view.freezerOnly?'checked':''}>Есть свободная заготовка</label><label class="check"><input type="checkbox" id="uses-prep-filter" ${view.usesPrep?'checked':''}>Используется заготовка</label><label class="check"><input type="checkbox" id="freeze-filter" ${view.canFreeze?'checked':''}>Можно заморозить целиком</label><span class="result-count">${list.length} из ${state.recipes.length}</span></div>${list.length?`<div class="recipe-grid">${list.map(r=>{const a=availability(free,r);const inMenu=state.menu.some(e=>e.recipeId===r.id&&!e.cooked);return `<article class="recipe-card"><button class="recipe-open" ${attrs('recipe',r.id)} aria-label="Открыть рецепт: ${esc(r.title)}"><span class="card-top">${foodIcon(r)}<span class="badge gray">${esc(r.category)}</span></span><span class="card-title">${esc(r.title)}</span><span class="meta"><span>${icon('people')}${fmt(r.servings)} порц.</span>${r.time?`<span>${icon('clock')}${r.time} мин</span>`:''}</span></button><div class="card-footer"><div class="card-badges">${inMenu?'<span class="badge gray">Уже в меню</span>':''}${a.has?`<span class="badge">${icon('snow')}${a.complete?'Есть заготовка':'Есть часть заготовки'}</span>`:''}</div><button class="add-circle" ${attrs('add-menu',r.id)} aria-label="Добавить в меню: ${esc(r.title)}">${icon('plus')}</button></div></article>`;}).join('')}</div>`:empty('Подходящих рецептов нет.',button('Сбросить фильтры','clear-filters'))}`;
}
function modeControl(r,entry,link,scope='menu'){
 const p=prep(link.prepId),mode=entry.prepModes?.[p.id]||(link.waterAllowed?'water':'fresh');
 return `<label class="prep-mode"><span>${esc(p.title)}</span><select data-prepmode="${esc(entry.id)}" data-scope="${scope}" data-prepid="${esc(p.id)}" ${entry.cooked?'disabled':''} aria-label="${esc(p.title)} для ${esc(r.title)}"><option value="fresh" ${mode==='fresh'?'selected':''}>Приготовить свежее</option><option value="stock" ${mode==='stock'?'selected':''}>Использовать из морозилки</option>${link.waterAllowed?`<option value="water" ${mode==='water'?'selected':''}>Использовать воду</option>`:''}</select></label>`;
}
function menuCard(e,a){const r=recipe(e.recipeId);return `<article class="menu-item ${e.cooked?'cooked':''}"><div class="menu-item-head"><button class="menu-recipe" ${attrs('recipe',r.id)}>${foodIcon(r)}<span>${esc(r.title)}</span></button><div class="menu-tools"><button class="icon-button ${e.pinned?'selected':''}" ${attrs('pin',e.id)} aria-label="${e.pinned?'Открепить':'Закрепить'} ${esc(r.title)}" aria-pressed="${e.pinned}">${icon('pin')}</button>${!e.cooked&&!e.pinned&&e.meal!=='extra'?iconButton(`Заменить ${r.title}`,'replace',e.id,'refresh'):''}${iconButton(`Убрать ${r.title}`,'remove-menu',e.id,'close')}</div></div><div class="menu-controls"><label class="inline-label">Порций<input type="number" min="0.5" max="100" step="0.5" value="${e.servings}" data-servings="${esc(e.id)}" aria-label="Порций: ${esc(r.title)}" ${e.cooked?'disabled':''}></label>${button(e.cooked?'Отменить отметку':`${icon('check')}Приготовлено`,e.cooked?'undo-cook':'cook',e.id,e.cooked?'button subtle':'button primary')}</div>${!e.cooked&&r.freezePrepId?`<label class="check whole-stock"><input type="checkbox" data-whole="${esc(e.id)}" ${e.wholeMode==='stock'?'checked':''}>Взять готовое блюдо из морозилки</label>`:''}${!e.cooked?`<div class="prep-modes">${r.preparations.map(l=>modeControl(r,e,l)).join('')}</div>`:''}${a?.allocations.filter(x=>x.mode==='stock'||x.whole).map(x=>`<p class="allocation-note">${esc(prep(x.prepId).title)}: из запаса ${quantity(x.used,prep(x.prepId).unit)}${x.used<x.needed?`; ещё ${quantity(round(x.needed-x.used),prep(x.prepId).unit)} — приготовить, продукты в покупках`:''}</p>`).join('')||''}${!e.cooked&&(r.preparations.length||r.freezePrepId)?`<div class="additional-preps">${r.preparations.map(l=>button(`Ещё в морозилку: ${esc(prep(l.prepId).title)}`,'plan-prep',l.prepId,'text-button')).join('')}${r.freezePrepId?button('Заготовить это блюдо','plan-prep',r.freezePrepId,'text-button'):''}</div>`:''}</article>`;}
function renderMenu(){const plan=allocate(state);return `${heading('Меню',`${button(`${icon('refresh')}Случайное`,'random')}${button(`${icon('spark')}По пожеланиям`,'quiz')}`)}<div class="toolbar menu-toolbar"><label class="inline-label">Дней<input type="number" id="menu-days" min="1" max="30" value="${state.days}"></label><span class="muted">По ${state.days} на каждый приём пищи</span>${button('Новое меню','new-week')}${button(`${icon('bag')}Покупки`,'shopping','','button primary')}</div><div class="meal-sections">${meals.map(([id,title])=>{const list=state.menu.filter(e=>e.meal===id);return `<section class="meal-section"><header class="section-line"><h2>${title} <span class="counter">${list.length}${id!=='extra'?` / ${state.days}`:''}</span></h2><button class="button small-button" data-action="browse-meal" data-meal="${id}">${icon('plus')}Добавить</button></header>${list.length?`<div class="menu-list">${list.map(e=>menuCard(e,plan.entries.find(a=>a.entryId===e.id))).join('')}</div>`:empty(id==='breakfast'&&!state.recipes.some(r=>r.category==='Завтраки')?'Добавь рецепты завтраков для автоматического подбора.':id==='extra'?'Салаты и десерты добавляются вручную.':'Блюда не выбраны.')}</section>`;}).join('')}</div>${renderProduction(plan)}`;}
function renderProduction(plan){return `<section class="production-section"><header class="section-line"><h2>Заготовить в морозилку <span class="counter">${state.prepPlans.length}</span></h2>${button(`${icon('plus')}Запланировать`,'plan-prep')}</header>${state.prepPlans.length?`<div class="production-list">${state.prepPlans.map(p=>{const t=prep(p.prepId),r=t.sourceRecipeId&&recipe(t.sourceRecipeId);return `<article class="panel production-item"><div class="section-line"><h3>${esc(t.emoji)} ${esc(t.title)}</h3>${iconButton('Убрать из плана','remove-production',p.id,'close')}</div><div class="menu-controls"><span>${quantity(p.amount,t.unit)}</span>${button(p.cooked?'Отменить отметку':'Заготовлено',p.cooked?'undo-production':'finish-production',p.id,p.cooked?'button subtle':'button primary')}</div>${r&&!p.cooked?`<div class="prep-modes">${r.preparations.map(l=>modeControl(r,p,l,'production')).join('')}</div>`:''}${button('Состав и приготовление','show-prep',t.id,'text-button')}</article>`;}).join('')}</div>`:''}</section>`;}
const shoppingSignature=i=>JSON.stringify([i.amount,i.amountMax,i.unquantified]);
function shoppingFlag(i){const f=state.shoppingStatus[i.key];return f?.signature===shoppingSignature(i)?f:{signature:shoppingSignature(i),bought:false,home:false};}
function shoppingQuantity(i){return quantity(i.amount,i.unit,i.amountMax)+(i.unquantified&&i.amount!=null?' + по необходимости':'');}
function renderShopping(){const items=allocate(state).shopping,remaining=items.filter(i=>{const f=shoppingFlag(i);return !f.home&&!f.bought;}).length;return `${heading('Покупки',`${button(`${icon('copy')}Скопировать`,'copy-shopping')}${button('Печать','print')}`)}${items.length?`<div class="section-line"><span>Осталось купить: <b>${remaining}</b> из ${items.length}</span>${button('Сбросить отметки','reset-shopping','','text-button')}</div>${[...new Set([...groups,...items.map(i=>i.group)])].map(g=>{const list=items.filter(i=>i.group===g);if(!list.length)return '';return `<section class="shopping-group"><h2>${esc(g)}</h2>${list.map(i=>{const f=shoppingFlag(i);return `<article class="shopping-item ${f.home||f.bought?'done':''}"><input type="checkbox" data-bought="${esc(i.key)}" aria-label="Куплено: ${esc(i.name)}" ${f.bought?'checked':''} ${f.home?'disabled':''}><div class="item-main"><div class="item-title"><span>${esc(i.name)} ${i.optionalOnly?'<span class="badge gray">По желанию</span>':''}</span><b>${shoppingQuantity(i)}</b></div><details><summary>Для чего · ${i.sources.length}</summary>${i.sources.map(s=>`<p class="shopping-source"><span>${esc(s.label)}</span><span>${s.unquantified&&s.amount===0?'по необходимости':quantity(s.amount,i.unit,s.amountMax)}${s.optional?' · по желанию':''}${s.note?` · ${esc(s.note)}`:''}</span></p>`).join('')}</details>${i.sources.some(s=>s.forFreezer)?'<span class="badge">Включает заготовку в морозилку</span>':i.sources.some(s=>s.prepTitle)?'<span class="badge">Включает продукты для заготовки</span>':''}<button class="text-button" data-action="home" data-key="${esc(i.key)}">${f.home?'Вернуть в покупки':'Есть дома'}</button></div></article>`;}).join('')}</section>`;}).join('')}`:empty('Список пуст. Добавь блюда или запланируй заготовку.',button('Открыть меню','menu','','button primary'))}`;}
function renderFreezer(){const plan=allocate(state),list=state.stock.filter(l=>(view.showEmpty||l.amount>0)&&norm(prep(l.prepId).title+' '+l.note).includes(norm(view.stockSearch))).sort((a,b)=>a.date.localeCompare(b.date));return `${heading('Морозилка',`${button('Запланировать заготовку','plan-prep')}${button(`${icon('plus')}Добавить готовый запас`,'new-stock','','button primary')}`)}<div class="toolbar"><label class="search">${icon('search')}<input id="stock-search" type="search" placeholder="Найти заготовку" aria-label="Найти заготовку" value="${esc(view.stockSearch)}"></label></div><div class="filters"><label class="check"><input type="checkbox" id="show-empty" ${view.showEmpty?'checked':''}>Показать закончившиеся</label>${button('Виды заготовок','prep-types','','text-button')}</div>${list.length?`<div class="freezer-grid">${list.map(l=>{const p=prep(l.prepId),left=plan.lots.find(x=>x.id===l.id)?.remaining??l.amount,reserved=round(l.amount-left);const uses=state.recipes.filter(r=>r.freezePrepId===p.id||r.preparations.some(x=>x.prepId===p.id));return `<article class="stock-card ${l.amount<=0?'exhausted':''}"><div class="section-line">${foodIcon(p)}<span class="muted">${dateLabel(l.date)}</span></div><h3>${esc(p.title)}</h3><div class="stock-number">${quantity(l.amount,p.unit)}</div>${reserved>0?`<p class="allocation-note">В плане: ${quantity(reserved,p.unit)} · свободно: ${quantity(left,p.unit)}</p>`:''}${l.note?`<p class="small muted">${esc(l.note)}</p>`:''}<div class="stock-links">${uses.map(r=>button(esc(r.title),'recipe',r.id,'text-button')).join('')}</div><div class="actions">${button('Изменить','edit-stock',l.id)}${button('Использовано','use-stock',l.id)}</div></article>`;}).join('')}</div>`:empty('Готовых запасов пока нет.',button('Добавить запас','new-stock','','button primary'))}`;}
function renderData(){return `${heading('Мои данные')}<div class="backup-grid"><section class="panel"><h2>Резервная копия</h2><p>Рецепты, фотографии, меню и морозилка в одном файле.</p>${button(`${icon('download')}Скачать копию`,'export','','button primary')}</section><section class="panel"><h2>Импорт</h2><p>Заменяет текущую книгу. Подходит для переноса на другое устройство.</p><label class="button file-label">Выбрать файл<input id="import-file" type="file" accept="application/json,.json"></label></section><section class="panel full"><p>Данные сохраняются на этом устройстве. Между телефоном и компьютером автоматической синхронизации нет. При очистке данных сайта понадобится резервная копия.</p>${hasPrevious?button('Скачать копию до последнего обновления или импорта','export-previous','','text-button'):''}</section>${state.history.length?`<section class="panel full"><h2>История меню</h2>${[...state.history].reverse().map(h=>`<div class="history-item"><b>${new Date(h.date).toLocaleDateString('ru-RU')}</b><p>${esc(h.dishes.join(' · '))}</p></div>`).join('')}</section>`:''}</div>`;}
function ingredientsList(items){let section='';return `<ul class="detail-ingredients">${items.map(i=>{const title=i.section!==section&&i.section?`<li class="ingredient-section">${esc(i.section)}</li>`:'';section=i.section;return `${title}<li><span>${esc(i.name)}${i.optional?'<span class="badge gray">По желанию</span>':''}${i.note?`<small>${esc(i.note)}</small>`:''}</span><span>${quantity(i.amount,i.unit,i.amountMax)}</span></li>`;}).join('')}</ul>`;}
function showRecipe(id){const r=recipe(id);if(!r)return;const a=availability(remainingState(state),r);showModal(r.title,`<div class="detail-top">${foodIcon(r)}<span class="badge gray">${esc(r.category)}</span><span>${r.servings} порц.</span>${r.time?`<span>${r.time} мин</span>`:''}${r.videoUrl?`<a class="button" href="${esc(safeVideoUrl(r.videoUrl))}" target="_blank" rel="noopener noreferrer">Смотреть видео</a>`:''}</div>${a.has?`<div class="availability">${a.list.map(l=>`<p>❄ ${esc(prep(l.prepId).title)}: ${quantity(l.amount,prep(l.prepId).unit)} · на ${fmt(l.servings)} порц.</p>`).join('')}</div>`:''}<h3>Ингредиенты</h3>${ingredientsList(r.ingredients)}<h3>Приготовление</h3><ol class="detail-steps">${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${r.notes?`<p class="recipe-notes">${esc(r.notes)}</p>`:''}${r.preparations.length||r.freezePrepId?`<h3>Заготовки</h3><div class="detail-preps">${r.preparations.map(l=>`<div><b>${esc(prep(l.prepId).title)}</b><span>${quantity(l.amount,prep(l.prepId).unit,l.amountMax)}</span>${button('Запланировать','plan-prep',l.prepId,'text-button')}</div>`).join('')}${r.freezePrepId?`<div><b>Можно заморозить целиком</b>${button('Запланировать','plan-prep',r.freezePrepId,'text-button')}</div>`:''}</div>`:''}<div class="modal-actions">${button(`${icon('edit')}Редактировать`,'edit-recipe',r.id)}${button(`${icon('plus')}В меню`,'add-menu',r.id,'button primary')}</div>`);}
function showPrep(id){const p=prep(id);if(p.sourceRecipeId){showRecipe(p.sourceRecipeId);return;}showModal(p.title,`<p>Выход: ${quantity(p.yield,p.unit)}</p>${p.note?`<p class="small muted">${esc(p.note)}</p>`:''}${ingredientsList(p.ingredients)}<ol class="detail-steps">${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="modal-actions">${button('Редактировать','edit-prep',p.id)}${button('Запланировать','plan-prep',p.id,'button primary')}</div>`);}
function showAddMenu(id){const r=recipe(id),allowed=allowedMeals(r);showModal(`В меню: ${r.title}`,`<form id="add-menu-form" data-id="${esc(id)}"><div class="form-grid"><label>Приём пищи<select name="meal">${allowed.map(m=>`<option value="${m}" ${m===view.addMeal?'selected':''}>${mealTitle(m)}</option>`).join('')}</select></label><label>Порций<input name="servings" type="number" min="0.5" max="100" step="0.5" value="${r.servings}" required></label></div><div class="modal-actions">${button('Отмена','close')}<button type="submit" class="button primary">Добавить</button></div></form>`);}
function ingredientRow(i={id:uid(),...ingredient('',null,'г')}){return `<div class="ingredient-editor" data-ingredient-id="${esc(i.id)}"><div class="ingredient-row"><input name="iname" list="ingredients" placeholder="Продукт" aria-label="Название продукта" maxlength="200" value="${esc(i.name)}" required><input name="iamount" type="number" min="0.0001" max="10000000" step="any" placeholder="Кол-во" aria-label="Количество продукта" value="${i.amount??''}"><input name="imax" type="number" min="0.0001" max="10000000" step="any" placeholder="До" aria-label="Максимальное количество продукта" value="${i.amountMax??''}"><select name="iunit" aria-label="Единица измерения">${options(units,i.unit)}</select><button class="icon-button" type="button" ${attrs('remove-ingredient')} aria-label="Удалить ингредиент">${icon('close')}</button></div><div class="ingredient-extra"><label class="check"><input type="checkbox" name="ioptional" ${i.optional?'checked':''}>По желанию</label><input name="isection" placeholder="Часть рецепта" aria-label="Часть рецепта" value="${esc(i.section)}"><input name="inote" placeholder="Примечание" aria-label="Примечание к ингредиенту" value="${esc(i.note)}"><select name="igroup" aria-label="Группа покупок">${options(groups,groups.includes(i.group)?i.group:'Другое')}</select></div></div>`;}
function readIngredients(){return $$('.ingredient-editor',modal).map(row=>{const amount=$('[name=iamount]',row).value,max=$('[name=imax]',row).value;return {id:row.dataset.ingredientId,name:$('[name=iname]',row).value.trim(),amount:amount===''?null:Number(amount),amountMax:max===''?undefined:Number(max),unit:$('[name=iunit]',row).value,optional:$('[name=ioptional]',row).checked,section:$('[name=isection]',row).value.trim(),note:$('[name=inote]',row).value.trim(),group:$('[name=igroup]',row).value};});}
function ingredientEditor(items){return `<section class="form-section"><div class="section-line"><h3>Ингредиенты</h3><button type="button" class="button" ${attrs('add-ingredient')}>${icon('plus')}Добавить</button></div><div id="ingredient-rows">${items.map(ingredientRow).join('')}</div><datalist id="ingredients">${[...new Set(state.recipes.flatMap(r=>r.ingredients.map(i=>i.name)))].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><p class="field-help">«До» — верхняя граница диапазона. Если количество не указано, оставь поле пустым.</p></section>`;}
function readLinks(){return $$('.prep-link-editor',modal).map(el=>({prepId:$('[name=prepId]',el).value,amount:Number($('[name=prepAmount]',el).value),amountMax:$('[name=prepMax]',el).value?Number($('[name=prepMax]',el).value):undefined,strategy:$('[name=strategy]',el).value,waterAllowed:$('[name=waterAllowed]',el).checked,covers:$$('[name=cover]:checked',el).map(x=>x.value)}));}
function linkEditor(l,items){const types=state.prepTypes.filter(p=>!p.sourceRecipeId);return `<div class="prep-link-editor"><div class="form-grid"><label>Заготовка<select name="prepId">${types.map(p=>`<option value="${esc(p.id)}" ${p.id===l.prepId?'selected':''}>${esc(p.title)} · ${esc(p.unit)}</option>`).join('')}</select></label><div class="amount-range"><label>На весь рецепт<input name="prepAmount" type="number" min="0.0001" max="10000000" step="any" value="${l.amount}" required></label><label>До<input name="prepMax" type="number" min="0.0001" max="10000000" step="any" value="${l.amountMax??''}"></label></div><label class="full">Продукты для свежей заготовки<select name="strategy"><option value="embedded" ${l.strategy==='embedded'?'selected':''}>Отмеченные строки этого рецепта</option><option value="replace" ${l.strategy==='replace'?'selected':''}>Состав из карточки заготовки</option></select></label><label class="check full"><input type="checkbox" name="waterAllowed" ${l.waterAllowed?'checked':''}>Вместо заготовки можно использовать воду</label></div><p class="field-help">Какие строки заменяет готовая заготовка:</p><div class="cover-options">${items.filter(i=>i.name).map(i=>`<label class="check"><input type="checkbox" name="cover" value="${esc(i.id)}" ${l.covers.includes(i.id)?'checked':''}>${esc(i.name)}${i.section?` (${esc(i.section)})`:''}</label>`).join('')}</div><button type="button" class="text-button danger" ${attrs('remove-link')}>Убрать связь</button></div>`;}
function refreshLinks(){if(!$('#prep-links',modal))return;const links=readLinks(),items=readIngredients();$('#prep-links').innerHTML=links.map(l=>linkEditor(l,items)).join('');}
function openRecipeEditor(id){
 recipeDraft=id?clone(recipe(id)):{id:uid(),title:'',category:'Второе',emoji:'🍽️',servings:2,time:null,ingredients:[{id:uid(),...ingredient('',null,'г')}],steps:[],videoUrl:'',notes:'',preparations:[],freezePrepId:null,photo:''};draftPhoto=recipeDraft.photo||'';const r=recipeDraft;
 showModal(id?'Редактировать рецепт':'Новый рецепт',`<form id="recipe-form"><div class="form-grid"><label class="full">Название<input name="title" value="${esc(r.title)}" maxlength="200" required></label><label>Категория<select name="category">${options(categories,r.category)}</select></label><label>Иконка<select name="emoji" class="emoji-select">${options([...new Set([...emojiChoices,r.emoji])],r.emoji)}</select></label><label>Порций<input name="servings" type="number" min="0.5" max="100" step="0.5" value="${r.servings}" required></label><label>Время, минут<input name="time" type="number" min="1" max="10000" value="${r.time??''}" placeholder="Не указано"></label><label class="full">Ссылка на видео<input name="videoUrl" type="url" maxlength="3000" placeholder="https://…" value="${esc(r.videoUrl)}"></label><label class="full">Фотография<input type="file" id="recipe-photo" accept="image/jpeg,image/png,image/webp"></label><div id="photo-preview" class="full">${r.photo?`<img class="photo-preview" src="${esc(r.photo)}" alt="Фото блюда"><button type="button" class="text-button" ${attrs('remove-photo')}>Убрать фото</button>`:''}</div></div>${ingredientEditor(r.ingredients)}<label class="form-section">Приготовление<textarea name="steps" rows="6" placeholder="Каждый шаг — с новой строки">${esc(r.steps.join('\n'))}</textarea></label><label class="form-section">Заметки<textarea name="notes" rows="3">${esc(r.notes)}</textarea></label><section class="form-section"><h3>Морозилка</h3><label class="check freeze-recipe"><input name="canFreeze" type="checkbox" ${r.freezePrepId?'checked':''}>Можно заморозить готовое блюдо целиком</label><div class="section-line"><h3>Используемые заготовки</h3><button type="button" class="button" ${attrs('add-link')}>${icon('plus')}Связать</button></div><div id="prep-links">${r.preparations.map(l=>linkEditor(l,r.ingredients)).join('')}</div></section><div class="modal-actions">${id?`<button type="button" class="button danger" ${attrs('delete-recipe',id)}>Удалить</button>`:''}<button type="button" class="button" ${attrs('close')}>Отмена</button><button type="submit" class="button primary">Сохранить рецепт</button></div></form>`);
}
async function saveRecipe(form){const f=new FormData(form),ingredients=readIngredients();if(!ingredients.length)throw new Error('Добавь хотя бы один ингредиент.');const video=safeVideoUrl(f.get('videoUrl').trim());if(video===null)throw new Error('Для видео нужна ссылка с http:// или https://.');const r={...recipeDraft,title:f.get('title').trim(),category:f.get('category'),emoji:f.get('emoji'),servings:Number(f.get('servings')),time:f.get('time')?Number(f.get('time')):null,videoUrl:video,photo:draftPhoto,notes:f.get('notes').trim(),steps:f.get('steps').split('\n').map(s=>s.trim()).filter(Boolean),ingredients,preparations:readLinks()};
 const next=clone(state);if(f.has('canFreeze')){if(!r.freezePrepId){r.freezePrepId=uid();next.prepTypes.push({id:r.freezePrepId,title:r.title+' порциями',unit:'порц.',emoji:r.emoji,yield:r.servings,ingredients:[],steps:[],sourceRecipeId:r.id,note:''});}else{const p=next.prepTypes.find(p=>p.id===r.freezePrepId);Object.assign(p,{title:r.title+' порциями',emoji:r.emoji,yield:r.servings});}}else r.freezePrepId=null;
 const index=next.recipes.findIndex(x=>x.id===r.id);if(index<0)next.recipes.push(r);else next.recipes[index]=r;
 for(const e of next.menu.filter(e=>e.recipeId===r.id)){if(!allowedMeals(r).includes(e.meal))e.meal=allowedMeals(r)[0];e.prepModes=Object.fromEntries(r.preparations.map(l=>[l.prepId,e.prepModes[l.prepId]||defaultModes(r)[l.prepId]]));if(!r.freezePrepId)e.wholeMode='fresh';}
 validateBackup(next);if(await commit(next)){closeModal();toast('Рецепт сохранён');}
}
function showPrepTypes(){showModal('Виды заготовок',`<div class="prep-type-list">${state.prepTypes.map(p=>`<div><span>${esc(p.emoji)} ${esc(p.title)}</span>${button(p.sourceRecipeId?'Рецепт':'Изменить',p.sourceRecipeId?'recipe':'edit-prep',p.sourceRecipeId||p.id,'text-button')}</div>`).join('')}</div><div class="modal-actions">${button('Новый вид заготовки','new-prep','','button primary')}</div>`);}
function editPrep(id){prepDraft=id?clone(prep(id)):{id:uid(),title:'',emoji:'❄️',unit:'л',yield:1,ingredients:[],steps:[],sourceRecipeId:null,note:''};const p=prepDraft;if(p.sourceRecipeId){openRecipeEditor(p.sourceRecipeId);return;}
 showModal(id?'Редактировать заготовку':'Новый вид заготовки',`<form id="prep-form"><div class="form-grid"><label class="full">Название<input name="title" value="${esc(p.title)}" maxlength="200" required></label><label>Иконка<select name="emoji">${options([...new Set([...emojiChoices,p.emoji])],p.emoji)}</select></label><label>Единица<select name="unit" ${id?'disabled':''}>${options(units.filter(u=>!u.startsWith('по ')),p.unit)}</select></label><label class="full">Выход по этому составу<input name="yield" type="number" min="0.0001" max="10000000" step="any" value="${p.yield}" required></label></div>${ingredientEditor(p.ingredients)}<label class="form-section">Приготовление<textarea name="steps">${esc(p.steps.join('\n'))}</textarea></label><label class="form-section">Заметка<textarea name="note">${esc(p.note)}</textarea></label><div class="modal-actions"><button type="button" class="button" ${attrs('close')}>Отмена</button><button class="button primary" type="submit">Сохранить заготовку</button></div></form>`);
}
async function savePrep(form){const f=new FormData(form),p={...prepDraft,title:f.get('title').trim(),emoji:f.get('emoji'),unit:f.get('unit')||prepDraft.unit,yield:Number(f.get('yield')),ingredients:readIngredients(),steps:f.get('steps').split('\n').map(s=>s.trim()).filter(Boolean),note:f.get('note').trim()};if(await mutate(s=>{const index=s.prepTypes.findIndex(x=>x.id===p.id);if(index<0)s.prepTypes.push(p);else s.prepTypes[index]=p;})){closeModal();toast('Вид заготовки сохранён');}}
function editStock(id){stockDraft=id?clone(state.stock.find(l=>l.id===id)):{id:uid(),prepId:state.prepTypes[0]?.id,amount:1,date:localDate(),note:''};const l=stockDraft;if(!l.prepId){editPrep();return;}
 showModal(id?'Изменить запас':'Добавить готовый запас',`<form id="stock-form"><div class="form-grid"><label class="full">Заготовка<select name="prepId" id="stock-prep">${state.prepTypes.map(p=>`<option value="${esc(p.id)}" ${p.id===l.prepId?'selected':''}>${esc(p.title)} · ${esc(p.unit)}</option>`).join('')}</select></label><label>Количество<input name="amount" type="number" min="0" max="10000000" step="any" value="${l.amount}" required></label><label>Дата заморозки<input name="date" type="date" value="${l.date}" required></label><label class="full">Заметка<textarea name="note">${esc(l.note)}</textarea></label></div><div class="modal-actions">${id?`<button type="button" class="button danger" ${attrs('delete-stock',id)}>Удалить</button>`:`<button type="button" class="button" ${attrs('new-prep')}>Новый вид заготовки</button>`}<button class="button primary" type="submit">Сохранить запас</button></div></form>`);
}
async function saveStock(form){const f=new FormData(form),lot={...stockDraft,prepId:f.get('prepId'),amount:Number(f.get('amount')),date:f.get('date'),note:f.get('note').trim()};if(await mutate(s=>{const index=s.stock.findIndex(l=>l.id===lot.id);if(index<0)s.stock.push(lot);else s.stock[index]=lot;})){closeModal();toast('Запас сохранён');}}
function planPrep(id){const p=prep(id)||state.prepTypes[0];if(!p){editPrep();return;}showModal('Заготовить в морозилку',`<form id="production-form"><div class="form-grid"><label class="full">Заготовка<select name="prepId" id="production-type">${state.prepTypes.map(t=>`<option value="${esc(t.id)}" ${t.id===p.id?'selected':''}>${esc(t.title)} · ${esc(t.unit)}</option>`).join('')}</select></label><label>Количество<input name="amount" id="production-amount" type="number" min="0.0001" max="10000000" step="any" value="${p.yield}" required></label></div><p class="field-help">Продукты добавятся в покупки отдельно от блюд. Запас появится после отметки «Заготовлено».</p><div class="modal-actions">${button('Отмена','close')}<button class="button primary" type="submit">Добавить в план</button></div></form>`);}
function showProductionFinish(id){const p=state.prepPlans.find(p=>p.id===id),t=prep(p.prepId);showModal('Заготовка готова',`<form id="finish-production-form" data-id="${esc(id)}"><p>${esc(t.title)}</p><div class="form-grid"><label>Фактический выход (${esc(t.unit)})<input type="number" name="amount" min="0.0001" max="10000000" step="any" value="${p.amount}" required></label><label>Дата заморозки<input name="date" type="date" value="${localDate()}" required></label></div><div class="modal-actions">${button('Отмена','close')}<button class="button primary" type="submit">Заготовлено</button></div></form>`);}
function useStock(id){const l=state.stock.find(l=>l.id===id),p=prep(l.prepId);showModal('Использовано',`<form id="use-stock-form" data-id="${esc(id)}"><p>${esc(p.title)} · осталось ${quantity(l.amount,p.unit)}</p><label class="form-section">Списать (${esc(p.unit)})<input type="number" name="amount" min="0.0001" max="${l.amount}" step="any" value="${l.amount}" required></label><div class="modal-actions">${button('Отмена','close')}<button class="button primary" type="submit">Списать</button></div></form>`);}
function showQuiz(){const q=view.quiz;showModal('Подобрать меню',`<form id="quiz-form"><h3>Желаемые продукты</h3><div class="quiz-chips">${[['Курица','кур'],['Свинина','свинина'],['Говядина','говядина'],['Творог','творог'],['Рыба','форель'],['Грибы','гриб'],['Овощи','тыква'],['Фарш','фарш']].map(([label,value])=>`<label class="check"><input name="prefer" type="checkbox" value="${value}" ${q.prefer?.includes(value)?'checked':''}>${label}</label>`).join('')}</div><div class="form-grid"><label>Время на блюдо<select name="maxTime">${[[0,'Без ограничения'],[15,'До 15 минут'],[30,'До 30 минут'],[60,'До 60 минут']].map(([v,t])=>`<option value="${v}" ${(q.maxTime||0)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Порций на приём пищи<input type="number" name="servings" min="0.5" max="100" step="0.5" value="${q.servings||2}" required></label><label class="full">Исключить продукты<input name="exclude" value="${esc(q.exclude?.join(', ')||'')}" placeholder="Через запятую"></label><label class="check full"><input type="checkbox" name="freezer" ${q.freezer?'checked':''}>Только с доступными заготовками</label></div><p class="field-help">По ${state.days} завтраков, обедов и ужинов. Супы — только на обед. Закреплённое остаётся, повторы разрешены. Салаты и десерты добавляются вручную.</p><div class="modal-actions">${button('Отмена','close')}<button class="button primary" type="submit">Собрать меню</button></div></form>`);}
async function buildMenu(options={}){let result;if(await commit(s=>{result=generateMenu(s,options);s.menu=result.menu;return s;})){closeModal();go('menu');const missing=Object.entries(result.shortfalls).filter(([,n])=>n>0).map(([m,n])=>`${mealTitle(m).toLowerCase()}: не хватает ${n}`);toast(missing.length?`Меню собрано; ${missing.join(', ')}. Добавь подходящие рецепты.`:'Меню собрано');}}
function showCook(id){const e=state.menu.find(e=>e.id===id),a=allocate(state).entries.find(e=>e.entryId===id),used=a.allocations.filter(x=>x.used>0);ask('Отметить приготовленным?',used.length?`Будет списано: ${used.map(x=>`${prep(x.prepId).title} — ${quantity(x.used,prep(x.prepId).unit)}`).join('; ')}.`:'Продукты этого блюда исчезнут из покупок. Запасы не изменятся.',()=>commit(s=>finishCooking(s,id)),'Приготовлено');}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const exportState=(s=state,prefix='na-nedelyu')=>download(JSON.stringify({...s,exportedAt:new Date().toISOString()},null,2),`${prefix}-${localDate()}.json`);
async function importBackup(file){if(!file)return;if(file.size>75*1024*1024)throw new Error('Максимальный размер копии — 75 МБ.');const parsed=JSON.parse(await file.text()),incoming=validateBackup(migrateState(parsed));ask('Заменить книгу?',`В копии ${incoming.recipes.length} рецептов и ${incoming.stock.length} записей морозилки. Текущая книга будет сохранена как предыдущая копия.`,async()=>{const ok=await commit(incoming,true);if(ok)toast('Книга восстановлена');return ok;},'Восстановить');}
async function loadPhoto(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw new Error('Нужно изображение JPEG, PNG или WebP до 15 МБ.');const bitmap=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();draftPhoto=canvas.toDataURL('image/jpeg',.8);$('#photo-preview').innerHTML=`<img class="photo-preview" src="${draftPhoto}" alt="Фото блюда"><button type="button" class="text-button" ${attrs('remove-photo')}>Убрать фото</button>`;}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();const {action,id,key}=el.dataset;
 try{switch(action){
 case 'close':closeModal();break;
 case 'data':closeModal();go('data');break;case 'menu':closeModal();go('menu');break;case 'shopping':go('shopping');break;
 case 'category':view.category=el.dataset.value;render();break;
 case 'clear-filters':view.search='';view.category='';view.freezerOnly=false;view.usesPrep=false;view.canFreeze=false;render();break;
 case 'end-adding':view.addMeal=null;go('menu');break;
 case 'browse-meal':view.addMeal=el.dataset.meal;view.category=view.addMeal==='breakfast'?'Завтраки':view.addMeal==='dinner'?'Второе':'';view.search='';view.freezerOnly=false;view.usesPrep=false;view.canFreeze=false;go('recipes');break;
 case 'recipe':showRecipe(id);break;case 'new-recipe':openRecipeEditor();break;case 'edit-recipe':openRecipeEditor(id);break;case 'add-menu':showAddMenu(id);break;
 case 'add-ingredient':$('#ingredient-rows').insertAdjacentHTML('beforeend',ingredientRow());$$('[name=iname]',modal).at(-1).focus();break;
 case 'remove-ingredient':el.closest('.ingredient-editor').remove();refreshLinks();break;
 case 'add-link':{const p=state.prepTypes.find(p=>!p.sourceRecipeId);if(!p)throw new Error('Сначала добавь вид заготовки в морозилке.');$('#prep-links').insertAdjacentHTML('beforeend',linkEditor({prepId:p.id,amount:p.yield,covers:[],strategy:'embedded',waterAllowed:false},readIngredients()));break;}
 case 'remove-link':el.closest('.prep-link-editor').remove();break;
 case 'remove-photo':draftPhoto='';$('#photo-preview').innerHTML='';$('#recipe-photo').value='';break;
 case 'delete-recipe':ask('Удалить рецепт?',`«${recipe(id).title}» исчезнет из книги и меню. Запасы останутся.`,()=>mutate(s=>{const r=s.recipes.find(r=>r.id===id);for(const p of s.prepTypes.filter(p=>p.sourceRecipeId===id)){p.ingredients=clone(r.ingredients);p.steps=clone(r.steps);p.sourceRecipeId=null;}s.recipes=s.recipes.filter(r=>r.id!==id);s.menu=s.menu.filter(e=>e.recipeId!==id);}), 'Удалить');break;
 case 'quiz':showQuiz();break;case 'random':view.quiz={};await buildMenu();break;
 case 'pin':await mutate(s=>{const e=s.menu.find(e=>e.id===id);e.pinned=!e.pinned;});break;
 case 'remove-menu':await mutate(s=>{s.menu=s.menu.filter(e=>e.id!==id);});break;
 case 'replace':{const e=state.menu.find(e=>e.id===id),q=view.quiz;let candidates=state.recipes.filter(r=>r.id!==e.recipeId&&allowedMeals(r).includes(e.meal)&&(!q.maxTime||(r.time&&r.time<=q.maxTime))&&!q.exclude?.some(x=>r.ingredients.some(i=>norm(i.name).includes(norm(x)))));if(q.freezer)candidates=candidates.filter(r=>availability(remainingState(state,state.menu.filter(x=>x.id!==id)),r).has);if(!candidates.length){toast('Других подходящих рецептов нет');break;}const counts={};state.menu.forEach(e=>counts[e.recipeId]=(counts[e.recipeId]||0)+1);const min=Math.min(...candidates.map(r=>counts[r.id]||0));candidates=candidates.filter(r=>(counts[r.id]||0)===min);const r=candidates[Math.floor(Math.random()*candidates.length)];await mutate(s=>{s.menu[s.menu.findIndex(x=>x.id===id)]=newEntry(r,e.meal,e.servings);});break;}
 case 'cook':showCook(id);break;case 'undo-cook':await commit(s=>undoCooking(s,id));toast('Отметка отменена, запас возвращён');break;
 case 'new-week':ask('Новое меню?','Список блюд сохранится в истории. Меню, план заготовок и отметки покупок очистятся; запасы останутся.',()=>mutate(s=>{if(s.menu.length)s.history=[...s.history,{date:new Date().toISOString(),dishes:s.menu.map(e=>`${mealTitle(e.meal)}: ${s.recipes.find(r=>r.id===e.recipeId).title}`)}].slice(-50);s.menu=[];s.prepPlans=[];s.shoppingStatus={};}),'Начать');break;
 case 'home':{const i=allocate(state).shopping.find(x=>x.key===key);await mutate(s=>{s.shoppingStatus[key]={...shoppingFlag(i),home:!shoppingFlag(i).home};});break;}
 case 'reset-shopping':await mutate(s=>{s.shoppingStatus={};});break;
 case 'copy-shopping':{const items=allocate(state).shopping.filter(i=>{const f=shoppingFlag(i);return !f.bought&&!f.home;});const text='Покупки\n\n'+items.map(i=>`☐ ${i.name} — ${shoppingQuantity(i)}${i.optionalOnly?' (по желанию)':''}${i.sources.some(s=>s.forFreezer)?' [включая заготовки в морозилку]':''}`).join('\n');try{await navigator.clipboard.writeText(text);toast('Список скопирован');}catch{download(text,'pokupki.txt','text/plain');}break;}
 case 'print':window.print();break;
 case 'prep-types':showPrepTypes();break;case 'show-prep':showPrep(id);break;case 'edit-prep':editPrep(id);break;case 'new-prep':editPrep();break;
 case 'new-stock':editStock();break;case 'edit-stock':editStock(id);break;case 'use-stock':useStock(id);break;
 case 'delete-stock':ask('Удалить запас?','Запись исчезнет из морозилки. План и покупки пересчитаются.',()=>mutate(s=>{s.stock=s.stock.filter(l=>l.id!==id);}), 'Удалить');break;
 case 'plan-prep':planPrep(id);break;
 case 'remove-production':await mutate(s=>{s.prepPlans=s.prepPlans.filter(p=>p.id!==id);});break;
 case 'finish-production':showProductionFinish(id);break;
 case 'undo-production':await commit(s=>undoProduction(s,id));toast('Отметка отменена');break;
 case 'export':exportState();break;
 case 'export-previous':{const previous=await readStorage('previous');if(previous)exportState(previous,'na-nedelyu-previous');break;}
 }}catch(err){if(modal.open)dialogError(err.message);else toast(err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='recipe-search'){view.search=e.target.value;render();}if(e.target.id==='stock-search'){view.stockSearch=e.target.value;render();}});
document.addEventListener('change',async e=>{const el=e.target;try{
 const filters={'freezer-filter':'freezerOnly','uses-prep-filter':'usesPrep','freeze-filter':'canFreeze','show-empty':'showEmpty'};
 if(filters[el.id]){view[filters[el.id]]=el.checked;render();}
 if(el.id==='menu-days'){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>30)throw new Error('Число дней — от 1 до 30.');await mutate(s=>{s.days=n;});}
 if(el.dataset.servings){const n=Number(el.value);if(!Number.isFinite(n)||n<.5||n>100)throw new Error('Порций должно быть от 0,5 до 100.');await mutate(s=>{s.menu.find(e=>e.id===el.dataset.servings).servings=n;});}
 if(el.dataset.prepmode){const value=el.value;await mutate(s=>{const list=el.dataset.scope==='production'?s.prepPlans:s.menu;list.find(e=>e.id===el.dataset.prepmode).prepModes[el.dataset.prepid]=value;});}
 if(el.dataset.whole)await mutate(s=>{s.menu.find(e=>e.id===el.dataset.whole).wholeMode=el.checked?'stock':'fresh';});
 if(el.dataset.bought){const i=allocate(state).shopping.find(i=>i.key===el.dataset.bought);await mutate(s=>{s.shoppingStatus[i.key]={...shoppingFlag(i),bought:el.checked};});}
 if(el.name==='iname'){const row=el.closest('.ingredient-editor'),name=el.value.trim(),known=state.recipes.flatMap(r=>r.ingredients).find(i=>norm(i.name)===norm(name));if(known)$('[name=igroup]',row).value=known.group;refreshLinks();}
 if(el.id==='production-type')$('#production-amount').value=prep(el.value).yield;
 if(el.id==='recipe-photo')await loadPhoto(el.files[0]);
 if(el.id==='import-file')await importBackup(el.files[0]);
 }catch(err){if(modal.open)dialogError(err.message);else{toast(err.message);render();}}});
document.addEventListener('submit',async e=>{if(!e.target.closest('#modal'))return;e.preventDefault();const form=e.target,submit=$('[type=submit]',form);submit.disabled=true;try{
 if(form.id==='recipe-form')await saveRecipe(form);
 if(form.id==='prep-form')await savePrep(form);
 if(form.id==='stock-form')await saveStock(form);
 if(form.id==='add-menu-form'){const f=new FormData(form),r=recipe(form.dataset.id);if(state.menu.length>=300)throw new Error('В одном меню может быть до 300 блюд.');if(await mutate(s=>s.menu.push(newEntry(r,f.get('meal'),Number(f.get('servings')))))){closeModal();toast(`${r.title} добавлено в меню`);}}
 if(form.id==='production-form'){const f=new FormData(form),p=prep(f.get('prepId')),r=p.sourceRecipeId&&recipe(p.sourceRecipeId);if(!r&&!p.ingredients.length)throw new Error('Сначала добавь состав в карточку заготовки.');if(await mutate(s=>s.prepPlans.push({id:uid(),prepId:p.id,amount:Number(f.get('amount')),cooked:false,prepModes:r?defaultModes(r):{}}))){closeModal();go('menu');toast('Заготовка добавлена в план и покупки');}}
 if(form.id==='finish-production-form'){const f=new FormData(form);if(await commit(s=>finishProduction(s,form.dataset.id,Number(f.get('amount')),f.get('date')))){closeModal();toast('Запас добавлен в морозилку');}}
 if(form.id==='quiz-form'){const f=new FormData(form),aliases={'грибы':'шампиньоны','курица':'кур','рыба':'форель'};view.quiz={prefer:f.getAll('prefer'),exclude:f.get('exclude').split(',').map(x=>x.trim()).filter(Boolean).map(x=>aliases[norm(x)]||x),maxTime:Number(f.get('maxTime')),servings:Number(f.get('servings')),freezer:f.has('freezer')};await buildMenu(view.quiz);}
 if(form.id==='use-stock-form'){const f=new FormData(form),amount=Number(f.get('amount')),id=form.dataset.id,lot=clone(state.stock.find(l=>l.id===id));if(!Number.isFinite(amount)||amount<=0||amount>lot.amount)throw new Error('Количество превышает запас.');if(await mutate(s=>{s.stock.find(l=>l.id===id).amount=round(lot.amount-amount);})){showModal('Запас обновлён',`<p>Осталось ${quantity(round(lot.amount-amount),prep(lot.prepId).unit)}.</p><div class="modal-actions"><button class="button" id="undo-stock-use">Отменить списание</button>${button('Готово','close','','button primary')}</div>`);$('#undo-stock-use').onclick=async()=>{if(await mutate(s=>{const l=s.stock.find(l=>l.id===id);if(l)l.amount=round(l.amount+amount);else s.stock.push(lot);})){closeModal();toast('Запас возвращён');}};}}
 }catch(err){dialogError(err.message);}finally{submit.disabled=false;}});
window.addEventListener('hashchange',()=>{view.page=location.hash.slice(1)||'recipes';render();window.scrollTo({top:0});});
try{
 const old=await openStorage();
 state=old?validateBackup(migrateState(old)):initialState();
 if(!old||old.schemaVersion!==2)await saveStorage(state,old);
 hasPrevious=!!(await readStorage('previous'));render();
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
}catch(err){$('#app').innerHTML=`<main class="panel recovery"><h1>Не удалось открыть книгу</h1><p>Сохранённые данные не перезаписаны.</p><p>${esc(err.message)}</p><button class="button" id="download-recovery">Скачать исходные данные</button></main>`;$('#download-recovery').onclick=async()=>{const raw=await readStorage('state');if(raw)exportState(raw,'na-nedelyu-recovery');};}
